</span></span><span><span>    getattrfunc tp_getattr;
</span></span><span><span>    setattrfunc tp_setattr;
</span></span><span><span>    PyAsyncMethods *tp_as_async; <span>/* formerly known as tp_compare (Python 2)
</span></span></span><span><span><span>                                    or tp_reserved (Python 3) */</span>
</span></span><span><span>    reprfunc tp_repr;
</span></span><span><span>
</span></span><span><span>    <span>/* Method suites for standard classes */</span>
</span></span><span><span>
</span></span><span><span>    PyNumberMethods *tp_as_number;
</span></span><span><span>    PySequenceMethods *tp_as_sequence;
</span></span><span><span>    PyMappingMethods *tp_as_mapping;
